using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEngine;
public static class Native49PackedScriptProviders{
 public static string Audit(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Stopped/ready required");var r=BuildReport.GetLatestReport();if(r==null)throw new Exception("Actual BuildReport required");var rows=new JArray();foreach(var p in r.packedAssets)foreach(var i in p.contents){if(i.type!=typeof(MonoScript)&&!i.sourceAssetPath.EndsWith("Liminal.SDK.dll")&&i.sourceAssetPath!="Assets/Liminal/Resources/LimappConfig.asset")continue;rows.Add(new JObject{["packedAsset"]=p.shortPath,["packedID"]=i.id.ToString(),["offset"]=i.offset,["sourceAssetGUID"]=i.sourceAssetGUID.ToString(),["sourceAssetPath"]=i.sourceAssetPath,["packedSize"]=i.packedSize,["type"]=i.type==null?null:i.type.FullName});}
 var providers=new JArray();foreach(var path in new[]{"Packages/com.liminal.sdk/SDK/Assemblies/Core/Liminal.SDK.dll","Packages/com.liminal.sdk/SDK/Assemblies/Release/Liminal.SDK.dll"}){var scripts=new JArray();foreach(var s in AssetDatabase.LoadAllAssetsAtPath(path).OfType<MonoScript>()){AssetDatabase.TryGetGUIDAndLocalFileIdentifier(s,out string guid,out long id);var type=s.GetClass();scripts.Add(new JObject{["name"]=s.name,["class"]=type==null?null:type.FullName,["guid"]=guid,["localID"]=id,["json"]=EditorJsonUtility.ToJson(s)});}providers.Add(new JObject{["path"]=path,["scripts"]=scripts});}
 var root=(string)JObject.Parse(File.ReadAllText("Tools/URPMigration/FinalAndroid-current.json"))["stage"];var folder=root+"/PackedScriptProviders-"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ");Directory.CreateDirectory(folder);var report=folder+"/report.json";File.WriteAllText(report,new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["result"]=r.summary.result.ToString(),["outputPath"]=r.summary.outputPath,["pid"]=System.Diagnostics.Process.GetCurrentProcess().Id,["rows"]=rows,["nativeCoreRelease"]=providers,["files"]=new JArray(r.GetFiles().Select(f=>new JObject{["path"]=f.path,["role"]=f.role,["size"]=f.size}))}.ToString());File.WriteAllText("Tools/URPMigration/PackedScriptProviders-current.json",new JObject{["stage"]=folder}.ToString());return report;
 }
}
